mapper.select:
WITH changed AS (
  INSERT INTO channel_inputs(organization_uuid,workspace_uuid,channel_uuid,channel_type,account_id,message_id,scope_key,payload)
  SELECT #{scope.OrganizationUUID},#{scope.WorkspaceUUID},c.uuid,#{scope.ChannelType},#{scope.AccountID},#{input.MessageID},#{input.ScopeKey},#{input.Payload,sensitive=true}::jsonb
  FROM channels c WHERE c.organization_uuid=#{scope.OrganizationUUID} AND c.workspace_uuid=#{scope.WorkspaceUUID}
    AND c.uuid=#{scope.ChannelUUID} AND c.channel_type=#{scope.ChannelType} AND c.app_id=#{scope.AccountID}
    AND c.enabled AND c.binding_status='bound' AND c.deleted_at IS NULL
  ON CONFLICT(channel_uuid,channel_type,account_id,message_id) DO NOTHING
  RETURNING uuid,message_id,scope_key,payload,state,session_external_id,prepared_content,input_event_id,lease_owner,lease_until
) SELECT  FROM changed i

WITH resumed AS (
  UPDATE channel_inputs i SET state='received',lease_until=now(),updated_at=now()
  WHERE  AND i.scope_key=#{input.ScopeKey} AND i.message_id=#{input.MessageID}
  RETURNING i.uuid::text AS uuid
) SELECT uuid FROM resumed

WITH resumed AS (
  UPDATE channel_inputs i SET state='received',lease_until=now(),updated_at=now()
  WHERE  AND i.payload->>'chat_id'=#{chatID} AND i.payload->>'oauth_provider'=#{provider}
  RETURNING i.*
) SELECT  FROM resumed i ORDER BY i.created_at,i.uuid

mapper.update:
UPDATE channel_inputs i SET state='grouped',parent_uuid=#{anchorUUID},lease_owner='',updated_at=now()
WHERE  AND i.scope_key=#{batch.ScopeKey} AND i.lease_owner=#{owner} AND i.uuid<>#{anchorUUID}
  AND i.message_id IN #{id}

UPDATE channel_inputs i SET lease_owner='',lease_until=now()+interval '30 seconds',updated_at=now()
WHERE  AND i.uuid=#{inputUUID} AND i.lease_owner=#{owner}
  AND i.state IN ('buffering','prepared','accepted','command_sending')
